import { useState, useEffect, useCallback } from 'react';
import { motion, AnimatePresence, PanInfo } from 'framer-motion';
import { Calendar, User, ChevronLeft, ChevronRight, Tag, ArrowLeft, ArrowRight } from 'lucide-react';
import { Link } from 'react-router-dom';
import PageLayout from '@/components/layout/PageLayout';
import { getPublishedBlogs, type Blog } from '@/data/blogs-supabase';
import { Helmet } from 'react-helmet-async';

const BlogPage = () => {
  const [blogs, setBlogs] = useState<Blog[]>([]);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [direction, setDirection] = useState(0);

  useEffect(() => {
    loadBlogs();
  }, []);

  const loadBlogs = async () => {
    setIsLoading(true);
    setError(null);
    try {
      const { blogs: fetchedBlogs } = await getPublishedBlogs(1, 1000);
      setBlogs(fetchedBlogs);
    } catch (err) {
      console.error('Error loading blogs:', err);
      setError('Failed to load blog posts');
    } finally {
      setIsLoading(false);
    }
  };

  const formatDate = (dateString: string | null) => {
    if (!dateString) return 'No date';
    const date = new Date(dateString);
    return date.toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });
  };

  const handlePrevious = useCallback(() => {
    if (currentIndex > 0) {
      setDirection(-1);
      setCurrentIndex(currentIndex - 1);
    }
  }, [currentIndex]);

  const handleNext = useCallback(() => {
    if (currentIndex < blogs.length - 1) {
      setDirection(1);
      setCurrentIndex(currentIndex + 1);
    }
  }, [currentIndex, blogs.length]);

  // Keyboard navigation
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'ArrowLeft') {
        handlePrevious();
      } else if (e.key === 'ArrowRight') {
        handleNext();
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [handlePrevious, handleNext]);

  // Touch swipe handling
  const handleDragEnd = (_e: MouseEvent | TouchEvent | PointerEvent, info: PanInfo) => {
    const swipeThreshold = 100;
    const swipeVelocityThreshold = 500;
    
    // If drag distance is small, treat it as a click (don't navigate)
    if (Math.abs(info.offset.x) < 10 && Math.abs(info.velocity.x) < 100) {
      return;
    }
    
    if (info.offset.x > swipeThreshold || info.velocity.x > swipeVelocityThreshold) {
      handlePrevious();
    } else if (info.offset.x < -swipeThreshold || info.velocity.x < -swipeVelocityThreshold) {
      handleNext();
    }
  };

  // Calculate positions for card stack
  const getCardStyle = (index: number, currentIdx: number) => {
    const position = index - currentIdx;
    
    if (Math.abs(position) > 2) {
      return { display: 'none' };
    }
    
    const baseScale = 1 - Math.abs(position) * 0.05;
    const translateX = position * 20;
    const translateZ = -Math.abs(position) * 100;
    const opacity = position === 0 ? 1 : 0.7 - Math.abs(position) * 0.3;
    const rotateY = position * 2;
    
    return {
      scale: baseScale,
      x: `${translateX}%`,
      z: translateZ,
      opacity,
      rotateY,
      zIndex: 10 - Math.abs(position),
    };
  };

  return (
    <>
      <Helmet>
        <title>Blog - Electronic Music News | Origins Radio</title>
        <meta name="description" content="Stay updated with the latest electronic music news, artist interviews, and scene insights from Origins Radio." />
      </Helmet>
      
      <PageLayout showFooter={false} lockScroll={true}>
        <div className="blog-no-scroll fixed inset-0 overflow-hidden">
          <div className="absolute inset-0 -z-10 bg-gradient-to-br from-black via-gray-900 to-black" />
          
          {/* Header */}
          <div className="absolute top-0 left-0 right-0 z-20 px-4 sm:px-6 lg:px-8 py-8">
            <motion.div
              initial={{ opacity: 0, y: -20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.6 }}
              className="text-center"
            >
              <h1 className="text-4xl md:text-5xl font-bold text-white mb-2 font-newake">
                Electronic Music News
              </h1>
              <p className="text-lg text-gray-400">
                Stay updated with the latest from the electronic music scene
              </p>
            </motion.div>
          </div>

          {/* Loading State */}
          {isLoading && (
            <div className="flex justify-center items-center h-full">
              <div className="text-white text-xl">Loading posts...</div>
            </div>
          )}

          {/* Error State */}
          {error && (
            <div className="flex justify-center items-center h-full px-4">
              <div className="blog-glass rounded-lg p-8 text-center max-w-md">
                <p className="text-red-400">{error}</p>
              </div>
            </div>
          )}

          {/* Empty State */}
          {!isLoading && !error && blogs.length === 0 && (
            <div className="flex justify-center items-center h-full px-4">
              <div className="blog-glass rounded-lg p-8 text-center max-w-md">
                <p className="text-gray-400 text-lg">No blog posts published yet. Check back soon!</p>
              </div>
            </div>
          )}

              {/* 3D Card Stack */}
          {!isLoading && !error && blogs.length > 0 && (
            <>
              <div className="blog-stack-container absolute inset-0 flex items-center justify-center px-4">
                <AnimatePresence mode="wait">
                  {blogs.map((blog, index) => {
                    const position = index - currentIndex;
                    
                    if (Math.abs(position) > 2) return null;
                    
                    return (
                      <motion.div
                        key={blog.id}
                        className="blog-card-3d absolute w-full max-w-4xl"
                        initial={getCardStyle(index, currentIndex)}
                        animate={getCardStyle(index, currentIndex)}
                        transition={{
                          type: "spring",
                          stiffness: 300,
                          damping: 30,
                        }}
                        style={{
                          pointerEvents: position === 0 ? 'auto' : 'none',
                        }}
                      >
                        <motion.div
                          drag={position === 0 ? "x" : false}
                          dragConstraints={{ left: 0, right: 0 }}
                          dragElastic={0.2}
                          onDragEnd={handleDragEnd}
                          dragDirectionLock
                          dragMomentum={false}
                        >
                          <Link 
                            to={`/blog/${blog.slug}`} 
                            className={`block cursor-pointer ${position !== 0 ? 'pointer-events-none' : ''}`}
                          >
                          <article className="rounded-2xl bg-neutral-900/90 border border-white/10 shadow-2xl overflow-hidden backdrop-blur-sm">
                            {blog.cover_image_url && (
                              <div className="relative w-full aspect-[16/9] overflow-hidden">
                                <motion.img
                                  src={blog.cover_image_url}
                                  alt={blog.title}
                                  className="w-full h-full object-cover"
                                  style={{
                                    scale: position === 0 ? 1 : 0.95,
                                  }}
                                  transition={{ duration: 0.3 }}
                                />
                                <div className="absolute inset-0 bg-gradient-to-t from-neutral-900 via-transparent to-transparent" />
                              </div>
                            )}

                            <div className="p-8 md:p-12">
                              {blog.featured && (
                                <motion.span 
                                  className="inline-block px-3 py-1 bg-white/20 text-white text-xs font-semibold rounded-full mb-4"
                                  initial={{ opacity: 0, y: -10 }}
                                  animate={{ opacity: 1, y: 0 }}
                                  transition={{ delay: 0.2 }}
                                >
                                  FEATURED
                                </motion.span>
                              )}

                              <h2 className="text-3xl md:text-4xl font-bold text-white mb-6 font-newake leading-tight">
                                {blog.title}
                              </h2>

                              <div className="flex flex-wrap items-center gap-6 text-sm text-gray-400 mb-6">
                                <div className="flex items-center gap-2">
                                  <User className="w-4 h-4" />
                                  <span>{blog.author}</span>
                                </div>
                                <div className="flex items-center gap-2">
                                  <Calendar className="w-4 h-4" />
                                  <span>{formatDate(blog.published_at)}</span>
                                </div>
                              </div>

                              {blog.excerpt && (
                                <p className="text-gray-300 text-lg mb-6 line-clamp-3">
                                  {blog.excerpt}
                                </p>
                              )}

                              {blog.tags && blog.tags.length > 0 && (
                                <div className="flex flex-wrap items-center gap-2">
                                  <Tag className="w-4 h-4 text-gray-400" />
                                  {blog.tags.slice(0, 4).map((tag, idx) => (
                                    <span
                                      key={idx}
                                      className="px-3 py-1 bg-white/10 text-gray-300 text-xs rounded-full"
                                    >
                                      {tag}
                                    </span>
                                  ))}
                                  {blog.tags.length > 4 && (
                                    <span className="text-gray-400 text-xs">+{blog.tags.length - 4} more</span>
                                  )}
                                </div>
                              )}
                            </div>
                          </article>
                        </Link>
                        </motion.div>
                      </motion.div>
                    );
                  })}
                </AnimatePresence>
              </div>

              {/* Navigation Controls */}
              <div className="absolute bottom-8 left-0 right-0 z-30 flex items-center justify-center gap-8 px-4">
                <button
                  onClick={handlePrevious}
                  disabled={currentIndex === 0}
                  className="blog-nav-arrow w-14 h-14 rounded-full bg-white/10 border border-white/20 flex items-center justify-center text-white hover:bg-white/20 disabled:opacity-30 disabled:cursor-not-allowed"
                  aria-label="Previous blog post"
                >
                  <ArrowLeft className="w-6 h-6" />
                </button>

                <div className="flex flex-col items-center gap-2">
                  <div className="text-white text-sm font-medium">
                    {currentIndex + 1} / {blogs.length}
                  </div>
                  <div className="flex gap-1.5">
                    {blogs.slice(Math.max(0, currentIndex - 2), Math.min(blogs.length, currentIndex + 3)).map((_, idx) => {
                      const actualIndex = Math.max(0, currentIndex - 2) + idx;
                      return (
                        <button
                          key={actualIndex}
                          onClick={() => {
                            setDirection(actualIndex > currentIndex ? 1 : -1);
                            setCurrentIndex(actualIndex);
                          }}
                          className={`w-2 h-2 rounded-full transition-all ${
                            actualIndex === currentIndex
                              ? 'bg-white w-6'
                              : 'bg-white/30 hover:bg-white/50'
                          }`}
                          aria-label={`Go to blog post ${actualIndex + 1}`}
                        />
                      );
                    })}
                  </div>
                  <div className="text-gray-500 text-xs">
                    Use arrow keys or swipe
                  </div>
                </div>

                <button
                  onClick={handleNext}
                  disabled={currentIndex === blogs.length - 1}
                  className="blog-nav-arrow w-14 h-14 rounded-full bg-white/10 border border-white/20 flex items-center justify-center text-white hover:bg-white/20 disabled:opacity-30 disabled:cursor-not-allowed"
                  aria-label="Next blog post"
                >
                  <ArrowRight className="w-6 h-6" />
                </button>
              </div>
            </>
          )}
        </div>
      </PageLayout>
    </>
  );
};

export default BlogPage;

